'use strict';
const $=s=>document.querySelector(s);const app=$('#app');
const KEY='island-voyage-v1';let saved={};try{saved=JSON.parse(localStorage.getItem(KEY)||'{}')||{}}catch{}
let state={scene:-1,level:saved.level==='little'?'little':'growing',sound:saved.sound!==false,stamps:Array.isArray(saved.stamps)?saved.stamps.slice(0,24):[],...((Number.isInteger(saved.scene)&&saved.scene>=0&&saved.scene<=6)?{resume:saved.scene}:{})};
let round=0,selected=[],message='',complete=false,hintTimer,colour='#b95036',shape='●',drag=null,suppressClick=false;
const objects={bottle:[0,'Clay water bottle'],oar:[1,'Wooden oar'],coconut:[2,'Coconut'],basket:[3,'Woven basket'],banana:[4,'Bananas'],hat:[5,'Woven hat'],ray:[6,'Manta ray'],shell:[7,'Shell'],star:[8,'Starfish']};
const titles=['Get ready to explore','Coconuts for the journey','A sail of your own','Follow our manta friend','The secret lagoon','A lovely place to picnic','You did it, voyager!'];
const packing=[['bottle','We’ll get thirsty. Pack the clay water bottle.'],['hat','The sun is shining. Pack the woven hat.'],['banana','We’ll get hungry. Pack the bananas.'],['oar','Let’s paddle our canoe. Bring the wooden oar.']];
const tasks=[{prompt:'Find the letter A.',choices:['B','A','C'],answer:'A'},{prompt:'Find the letter B.',choices:['C','A','B'],answer:'B'},{prompt:'Find the letter C.',choices:['C','B','A'],answer:'C'},{prompt:'Which number matches these starfish?',stars:3,choices:['2','3','5'],answer:'3'},{prompt:'Finish the pattern. Coral, blue, coral, blue…',choices:['Coral','Blue'],answer:'Coral'},{prompt:'Which group has five shells?',choices:['2 shells','5 shells','3 shells'],answer:'5 shells'}];
function save(){try{localStorage.setItem(KEY,JSON.stringify({scene:state.scene,level:state.level,sound:state.sound,stamps:state.stamps}))}catch{}}
function art(id){let [i,label]=objects[id];return `<span class="art" role="img" aria-label="${label}" style="background-position:${i%3*50}% ${Math.floor(i/3)*50}%"></span>`}
function ray(){return `<div class="ray">${art('ray')}<span class="sparkles">· ✧ · ✦</span></div>`}
function speak(text){if(!state.sound||!('speechSynthesis'in window))return;window.speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(text);u.lang='en-GB';u.rate=.83;u.pitch=1.08;const voices=speechSynthesis.getVoices();u.voice=voices.find(v=>v.lang==='en-GB')||voices.find(v=>v.lang.startsWith('en'))||null;speechSynthesis.speak(u)}
function chime(){if(!state.sound)return;try{const C=window.AudioContext||window.webkitAudioContext;if(!C)return;const c=chime.ctx||(chime.ctx=new C());c.resume();[523,659,784].forEach((f,i)=>{const o=c.createOscillator(),g=c.createGain(),t=c.currentTime+i*.1;o.type='sine';o.frequency.value=f;g.gain.setValueAtTime(0,t);g.gain.linearRampToValueAtTime(.035,t+.02);g.gain.exponentialRampToValueAtTime(.001,t+.3);o.connect(g);g.connect(c.destination);o.start(t);o.stop(t+.35)})}catch{}}
function instruction(){if(complete)return 'Lovely helping! Tap the arrow when you’re ready.';switch(state.scene){case 0:return packing[round][1];case 1:return `Put ${target()} coconuts in the basket. Tap or drag each coconut.`;case 2:return 'Choose a colour and a shape. Tap the sail to decorate it.';case 3:return ['Our manta friend knows the way. Touch her to follow the sparkling trail.','There she is! Touch our manta friend again.','One more little glide. Follow our manta friend!'][round];case 4:return tasks[round].prompt;case 5:return ['Set out our woven basket for the picnic.','Put the water bottle beside our picnic.','Share the bananas with Moana.','Our picnic is finished. Put the shell back on the beach.'][round];default:return 'You packed, counted, created, and helped our manta friend. Thank you!'}}
function target(){return (state.level==='little'?[1,2,3]:[2,3,4,5])[round]}
function item(id){return `<button class="item" data-item="${id}" ${selected.includes(id)?'disabled':''} aria-label="${objects[id][1]}">${art(id)}<span>${objects[id][1]}</span></button>`}
function nextButton(){return `<button class="primary next" id="next" aria-label="Continue adventure">Let’s go &nbsp; →</button>`}
function sail(){return `<div class="sail" id="sail" role="button" tabindex="0" aria-label="Decorate the sail">${state.stamps.map(s=>`<span class="stamp" style="left:${s.x}%;top:${s.y}%;color:${s.c}">${s.s}</span>`).join('')}</div>`}
function content(){switch(state.scene){case 0:return `<div class="items">${['bottle','hat','banana','oar','shell'].map(item).join('')}</div><div class="dropzone" id="drop">${art('basket')}${selected.map(art).join('')}<span>${selected.length}/4 packed</span></div>`;case 1:return `<div class="count">${'●'.repeat(selected.length)}${'○'.repeat(target()-selected.length)}</div><div class="items">${Array.from({length:target()},(_,i)=>`<button class="item" data-item="c${i}" ${selected.includes('c'+i)?'disabled':''} aria-label="Coconut ${i+1}">${art('coconut')}</button>`).join('')}</div><div class="dropzone" id="drop">${art('basket')}<span>${selected.length} of ${target()} coconuts</span></div>`;case 2:return `${sail()}<div class="palette">${['#b95036','#207b88','#e2a73c','#4c8456'].map(c=>`<button class="swatch ${colour===c?'selected':''}" data-colour="${c}" aria-label="${{'#b95036':'Coral','#207b88':'Blue','#e2a73c':'Yellow','#4c8456':'Green'}[c]}" style="background:${c}" aria-pressed="${colour===c}"></button>`).join('')}</div><div class="palette" style="margin-top:12px">${['●','▲','✦'].map(s=>`<button class="shape ${shape===s?'selected':''}" data-shape="${s}" aria-label="${s==='●'?'Circle':s==='▲'?'Triangle':'Star'}" aria-pressed="${shape===s}">${s}</button>`).join('')}<button class="shape" id="undo" aria-label="Undo last stamp">↶</button></div><p class="caption">Your sail, your way.</p><button class="primary next" id="next">My sail is ready &nbsp; →</button>`;case 3:return `<div style="min-height:260px;display:flex;align-items:center;justify-content:${['flex-start','flex-end','center'][round]};padding:20px 10%"><button class="item" data-item="ray" style="width:170px;background:#d8eeea;border:0" aria-label="Follow the manta ray">${ray()}</button></div>`;case 4:{let t=tasks[round];return `${ray()}${t.stars?`<div>${Array.from({length:t.stars},()=>art('star')).join('')}</div>`:''}${round===4?'<div class="count" aria-label="Coral blue coral blue">🟠 🔵 🟠 🔵</div>':''}<div class="items choices">${t.choices.map((c,i)=>`<button class="item" data-choice="${i}" aria-label="${c}">${c.includes('shells')?`<span style="font-size:22px">${'🐚'.repeat(parseInt(c))}</span>`:c}</button>`).join('')}</div>`}case 5:return `<div class="items">${['basket','bottle','banana','shell'].map(item).join('')}</div><div class="dropzone" id="drop">${round===3?'The sandy beach':'Our picnic mat'} ${selected.filter(x=>x!=='shell').map(art).join('')}</div>`;case 6:return `${ray()}<div class="finish-sail">${sail()}</div><p>A basket packed. A beautiful sail.<br>A new friend in the lagoon.</p><button class="primary" id="replay">Another voyage &nbsp; ↻</button><br><button class="secondary" id="goodbye">All done for now</button>`}}
function render(){clearTimeout(hintTimer);app.innerHTML=`<div class="world"><header class="top"><div class="brand"><span>✧</span> MY FIRST ISLAND VOYAGE</div><div class="tools">${state.scene>=0?'<button class="round" id="home" aria-label="Pause adventure">⌂</button>':''}<button class="round" id="sound" aria-label="${state.sound?'Mute':'Enable'} sound">${state.sound?'♫':'♪̸'}</button><button class="round" id="settings" aria-label="Parent settings">⚙</button></div></header>${state.scene<0?`<section class="home">${ray()}<div class="intro"><div class="eyebrow">A little ocean adventure</div><h1>Moana<em>& the</em>Manta Ray</h1><p>A little helping.<br>A little magic. A whole ocean to explore.</p><button class="primary" id="start">${state.resume!==undefined&&state.resume<6?'Continue voyage':'Let’s set sail'} &nbsp; →</button><div class="caption">Sound on · Play at your own pace</div></div></section><div class="home-footer">Made for little hands & curious hearts</div>`:`<section class="play"><div class="steps" aria-label="Chapter ${state.scene+1} of 7">${titles.map((_,i)=>`<span class="step ${i===state.scene?'active':i<state.scene?'done':''}"></span>`).join('')}</div><div class="board"><div class="scene-label">${state.scene===6?'Our adventure is complete':`Chapter ${state.scene+1} · ${['Get ready','Count together','Make something','Ocean magic','Explore & learn','Care for our things'][state.scene]}`}</div><h2>${titles[state.scene]}</h2><div class="instruction"><p>${instruction()}</p><button class="round" id="listen" aria-label="Hear instruction again">♫</button></div>${content()}<div class="feedback" role="status" aria-live="polite">${message}</div>${complete?nextButton():''}</div></section>`}</div>`;bind();if(state.scene>=0&&!complete)hintTimer=setTimeout(()=>{let el=correctElement();if(el)el.classList.add('hint')},11000)}
function correctElement(){if(state.scene===0)return document.querySelector(`[data-item="${packing[round][0]}"]`);if(state.scene===4)return document.querySelector(`[data-choice="${tasks[round].choices.indexOf(tasks[round].answer)}"]`);if(state.scene===5)return document.querySelector(`[data-item="${['basket','bottle','banana','shell'][round]}"]`);return document.querySelector('[data-item]:not(:disabled)')||$('#sail')}
function enter(scene){state.scene=scene;round=0;selected=[];complete=false;message='';save();render();speak(instruction())}
function success(text){chime();message=text;render();speak(text+' '+instruction())}
function use(id){if(complete)return;if(state.scene===0){if(id!==packing[round][0]){message='Let’s look together.';render();correctElement()?.classList.add('hint');speak(instruction());return}selected.push(id);if(round===3)complete=true;else round++;success('Packed with care!')}else if(state.scene===1){if(selected.includes(id))return;selected.push(id);if(selected.length===target()){if(round===(state.level==='little'?2:3))complete=true;else {round++;selected=[]}success('Wonderful counting!')}else{message=`${selected.length}!`;render();speak(message)}}else if(state.scene===3){if(round===2)complete=true;else round++;success('What a beautiful glide!')}else if(state.scene===5){if(id!==['basket','bottle','banana','shell'][round]){speak(instruction());correctElement()?.classList.add('hint');return}selected.push(id);if(round===3)complete=true;else round++;success('Thank you for helping!')}}
function choose(i){if(complete)return;if(tasks[round].choices[i]!==tasks[round].answer){message='Have another little look.';render();correctElement()?.classList.add('hint');speak(instruction());return}if(round===(state.level==='little'?2:5))complete=true;else round++;success('You found it!')}
function bind(){const on=(id,fn)=>{const e=$(id);if(e)e.onclick=fn};on('#start',()=>enter(state.resume!==undefined&&state.resume<6?state.resume:0));on('#home',()=>{state.resume=state.scene;state.scene=-1;window.speechSynthesis?.cancel();render()});on('#sound',()=>{state.sound=!state.sound;save();if(!state.sound)window.window.speechSynthesis?.cancel();render();if(state.sound)speak('Sound is on.');});on('#settings',settings);on('#listen',()=>speak(instruction()));on('#next',()=>enter(state.scene+1));on('#replay',()=>{state.stamps=[];enter(0)});on('#goodbye',()=>{delete state.resume;state.scene=-1;save();render();speak('Goodbye, little voyager. See you another day.');});on('#undo',()=>{state.stamps.pop();save();render()});document.querySelectorAll('[data-item]').forEach(el=>{el.onclick=()=>{if(!suppressClick)use(el.dataset.item)};el.onpointerdown=e=>{if(e.pointerType==='mouse'&&e.button!==0)return;drag={el,id:el.dataset.item,x:e.clientX,y:e.clientY,clone:null};el.setPointerCapture(e.pointerId)};el.onpointermove=e=>{if(!drag||drag.el!==el)return;if(!drag.clone&&Math.hypot(e.clientX-drag.x,e.clientY-drag.y)>12){drag.clone=el.cloneNode(true);drag.clone.classList.add('dragging');drag.clone.style.width=el.offsetWidth+'px';document.body.appendChild(drag.clone)}if(drag.clone){drag.clone.style.left=e.clientX-el.offsetWidth/2+'px';drag.clone.style.top=e.clientY-60+'px';$('#drop')?.classList.add('over')}};el.onpointerup=e=>{if(!drag)return;const moved=!!drag.clone;if(moved){const zone=$('#drop'),r=zone?.getBoundingClientRect();drag.clone.remove();suppressClick=true;setTimeout(()=>suppressClick=false,100);if(r&&e.clientX>=r.left-25&&e.clientX<=r.right+25&&e.clientY>=r.top-25&&e.clientY<=r.bottom+25)use(drag.id);else if(!zone)use(drag.id)}$('#drop')?.classList.remove('over');drag=null};el.onpointercancel=()=>{drag?.clone?.remove();drag=null;$('#drop')?.classList.remove('over')}});document.querySelectorAll('[data-choice]').forEach(el=>el.onclick=()=>choose(Number(el.dataset.choice)));document.querySelectorAll('[data-colour]').forEach(el=>el.onclick=()=>{colour=el.dataset.colour;render()});document.querySelectorAll('[data-shape]').forEach(el=>el.onclick=()=>{shape=el.dataset.shape;render()});if(state.scene===2){const s=$('#sail');const stamp=(x,y)=>{if(state.stamps.length>=24)state.stamps.shift();state.stamps.push({x,y,c:colour,s:shape});save();render();chime()};s.onclick=e=>{const r=s.getBoundingClientRect();stamp((e.clientX-r.left)/r.width*100,(e.clientY-r.top)/r.height*100)};s.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();stamp(25+Math.random()*20,55+Math.random()*30)}}}}
function settings(){window.speechSynthesis?.cancel();clearTimeout(hintTimer);const overlay=document.createElement('div');overlay.className='modal-backdrop';overlay.innerHTML=`<section class="modal" role="dialog" aria-modal="true" aria-labelledby="settings-title"><h2 id="settings-title">For grown-ups</h2><label>Adventure level<select id="level"><option value="little" ${state.level==='little'?'selected':''}>Little voyager · 1–3</option><option value="growing" ${state.level==='growing'?'selected':''}>Growing voyager · 1–5</option></select></label><p>English narration uses this device’s available voice. Keep the ringer and media volume on. Tap ♫ to repeat a prompt.</p><p>Progress stays on this device. A chapter restarts when you return. Italian is planned for a later adventure.</p><button class="primary" id="close-settings">Back to the adventure</button><button class="secondary" id="restart">Start a fresh voyage</button></section>`;app.appendChild(overlay);$('#close-settings').focus();overlay.onkeydown=e=>{if(e.key==='Escape')close();if(e.key==='Tab'){const list=[...overlay.querySelectorAll('button,select')],a=list[0],b=list.at(-1);if(e.shiftKey&&document.activeElement===a){e.preventDefault();b.focus()}else if(!e.shiftKey&&document.activeElement===b){e.preventDefault();a.focus()}}};const close=()=>{const level=$('#level').value,changed=level!==state.level;state.level=level;save();if(changed&&state.scene>=0)enter(state.scene);else render();$('#settings')?.focus()};$('#close-settings').onclick=close;$('#restart').onclick=()=>{state.level=$('#level').value;state.stamps=[];delete state.resume;enter(0)}}
document.addEventListener('visibilitychange',()=>{if(document.hidden){window.speechSynthesis?.cancel();clearTimeout(hintTimer)}});render();
